import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm,readdir} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-qa-critico-sondas';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);

 const files=await readdir('/tmp/legendgirl-qa-critico-integral');
 const states={};for(const [key,prefix]of [['panic','besouro-riacho-1-'],['ground','etapa-RUNNING-'],['ending','etapa-COMPLETE-']])states[key]=JSON.parse(await readFile('/tmp/legendgirl-qa-critico-integral/'+files.find(f=>f.startsWith(prefix)&&f.endsWith('.json')),'utf8'));
 await evaluate(`window.probeStates=${JSON.stringify(states)}`);
 const reports=[];
 const motion=await evaluate(`(async()=>{
  const {restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');phase.state=restoreGardenState(probeStates.panic,'EASY');window.beetleFrames=[];let next=0;const wall=performance.now();game.setPaused(false);
  await new Promise(resolve=>{const frame=now=>{const s=phase.state,b=s.encounters.panic;if(!b||now-wall>1300){game.setPaused(true);resolve();return;}if(now-wall>=next){phase.render();const f=phase.renderer.frame(s),x=(b.x-f.ox)*f.scale,y=b.y*f.scale+f.oy,c=document.createElement('canvas');c.width=240;c.height=220;const ctx=c.getContext('2d');ctx.drawImage(phase.canvas,x-70*f.scale,y-100*f.scale,140*f.scale,120*f.scale,0,0,240,205);ctx.fillStyle='#203e28';ctx.font='14px sans-serif';ctx.fillText((now-wall).toFixed(0)+'ms',5,216);beetleFrames.push(c.toDataURL());next+=110;}requestAnimationFrame(frame);};requestAnimationFrame(frame);});return{label:'besouro em voo no host real',frames:beetleFrames.length};
 })()`);reports.push(motion);
 const frames=await evaluate('beetleFrames');for(let i=0;i<frames.length;i++)await writeFile(out+'/besouro-'+i+'.png',Buffer.from(frames[i].split(',')[1],'base64'));
 const sheet=await evaluate(`(()=>{const c=document.createElement('canvas');c.width=960;c.height=660;const ctx=c.getContext('2d');return Promise.all(beetleFrames.slice(0,12).map(async(src,i)=>{const im=new Image();im.src=src;await im.decode();ctx.drawImage(im,i%4*240,Math.floor(i/4)*220);})).then(()=>c.toDataURL());})()`);await writeFile(out+'/besouro-sequencia.png',Buffer.from(sheet.split(',')[1],'base64'));
 await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});await call('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:2});await new Promise(r=>setTimeout(r,350));
 for(const [label,key]of [['normal','ground'],['panico','panic']]){
  const points=await evaluate(`(async()=>{const {restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');phase.state=restoreGardenState(probeStates.${key},'EASY');game.setPaused(false);phase.render();const r=phase.canvas.getBoundingClientRect(),b=phase.renderer.controls();return Object.fromEntries(Object.entries(b).map(([k,v])=>[k,{x:r.left+v.x*r.width/phase.canvas.width,y:r.top+v.y*r.height/phase.canvas.height}]));})()`);
  const direction=label==='panico'?'left':'right';await call('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{...points[direction],id:1},{...points.jump,id:2}]});await new Promise(r=>setTimeout(r,130));
  const response=await evaluate(`({label:'${label}',input:phase.input.sample(),vx:phase.state.player.vx,vy:phase.state.player.vy,onGround:phase.state.player.onGround,panic:Boolean(phase.state.encounters.panic)})`);reports.push(response);
  const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/toque-'+label+'.png',Buffer.from(shot.result.data,'base64'));
  await call('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});await new Promise(r=>setTimeout(r,50));reports.push(await evaluate(`({label:'liberacao-${label}',input:phase.input.sample()})`));await evaluate('game.setPaused(true)');
 }
 const ending=await evaluate(`(async()=>{const {restoreGardenState}=await import('/src/js/garden/GardenSimulation.js');phase.state=restoreGardenState(probeStates.ending,'EASY');phase.state.age=60;game.setPaused(false);window.dispatchEvent(new KeyboardEvent('keydown',{code:'Space',bubbles:true}));await new Promise(r=>setTimeout(r,250));window.dispatchEvent(new KeyboardEvent('keyup',{code:'Space',bubbles:true}));game.setPaused(true);return{label:'apos encerramento e espaco',stage:phase.state.stage,age:phase.state.age,buttons:[...document.querySelectorAll('button')].filter(b=>b.getBoundingClientRect().width&&getComputedStyle(b).visibility!=='hidden').map(b=>b.innerText||b.getAttribute('aria-label'))};})()`);reports.push(ending);
 const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/fim-sem-acao.png',Buffer.from(shot.result.data,'base64'));
 console.log(JSON.stringify(reports));await writeFile('docs/diario-ia/qa-resultados/yuna/sondas-criticas.json',JSON.stringify(reports,null,2));await writeFile(out+'/resultado.json',JSON.stringify(reports,null,2));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
